### Contoh

`describe` mengelompokkan tes, dan `beforeEach` menyiapkan keadaan baru sebelum **setiap** tes, supaya tes tidak saling memengaruhi:

```js
describe('produkService', () => {
  let service;
  beforeEach(() => {
    service = buatProdukService(buatRepoMemori([...]));
  });

  it('menambah produk dan memberi id baru', async () => { ... });
  it('menolak nama yang sudah ada', async () => { ... });
});
```

`it` sama dengan `test`, hanya berbeda nama. Banyak tim memakai `describe` + `it` supaya kalimatnya terbaca: "produkService menambah produk dan memberi id baru".

langkah.keluaran:
import { describe, it, beforeEach } from 'node:test';
import assert from 'node:assert/strict';
import { buatProdukService } from '../src/services/produk.js';
import { buatRepoMemori } from '../src/repositories/produk.memori.js';

describe('produkService', () => {
  let service;
  beforeEach(() => {
    service = buatProdukService(buatRepoMemori([{ id: 1, nama: 'Kopi Susu', harga: 18000, stok: 5 }]));
  });

  it('menambah produk dan memberi id baru', async () => {
    const p = await service.tambah({ nama: 'Teh Tarik', harga: 12000 });
    assert.deepEqual(p, { id: 2, nama: 'Teh Tarik', harga: 12000, stok: 0 });
  });

  it('menolak nama yang sudah ada tanpa membedakan huruf besar', async () => {
    await assert.rejects(service.tambah({ nama: 'kopi susu', harga: 1000 }), { status: 409, kode: 'NAMA_SUDAH_ADA' });
